  'Your data': 'Vos données',
  'The download has what Caime keeps about you, as the app shows it to you: your profile, how you label people, the messages you sent, your actions, files, calls, devices and more. Never other people’s words, reports others made about you, or secrets.':
    'Le téléchargement contient ce que Caime garde sur vous, tel que l’application vous le montre : votre profil, vos étiquettes, les messages que vous avez envoyés, vos actions, fichiers, appels, appareils et plus. Jamais les mots des autres, les signalements faits à votre sujet, ni des secrets.',
